// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        vm.prank(address(0));
        c.transferOwnership(address(this));

        assertTrue(c.owner() == address(this));

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller != address(this)) {
            assertTrue(c.owner() == address(this));
        } else {
            assertTrue(c.owner() == newOwner);
        }
    }
}
